from flask import Flask, request

app = Flask(__name__)

@app.route('/tip')
def tip_calculator():
    total = float(request.args.get('total'))
    percentage = float(request.args.get('percentage'))

    tip = ((total * percentage) / 100)

    return f"<p>TIP: ${tip}</p>"

if __name__ == '__main__':
    app.run()

