from flask import Flask, request

app = Flask(__name__)

@app.route('/get_money', methods=['GET', 'POST'])
def get_money():
    user_name = request.form.get('user_name')
    amount = int(request.form.get('amount'))

    if not user_name or not amount:
        return "User name and/or amount missing", 400

    response = f"Sent {amount} to {user_name}"

    return response

