import numpy as np

class QuickBuck:
    def __init__(self):
        self.balance = np.random.choice(range(0, 10000))

    def deposit(self, amount):
        self.balance += amount

    def withdraw(self, amount):
        if amount > self.balance:
            print("Insufficient funds")
            return False
        else:
            self.balance -= amount
            return True

qb = QuickBuck()
qb.deposit(1234)
print(qb.balance)

qb.withdraw(500)
print(qb.balance)

